template:
struct BankAccount {
    balance: u32,
}

impl BankAccount {
    fn deposit(⟦receiver⟧, amount: u32) {
        self.balance += amount;
    }
}

fn main() {
    ⟦binding⟧ account = BankAccount { balance: 100 };
    account.deposit(50);
    println!("{}", account.balance);
}

tests:
#[test]
fn deposits_money() {
    let mut account = BankAccount { balance: 100 };
    account.deposit(50);
    assert_eq!(account.balance, 150);
}
